
const SOURCE_IMAGES={"151525":"data:image/png;base64,","151611":"data:image/png;base64,","151700":"data:image/png;base64,","151957":"data:image/png;base64,","152238":"data:image/png;base64,","152356":"data:image/png;base64,","152522":"data:image/png;base64,","152621":"data:image/png;base64,","152700":"data:image/png;base64,","152755":"data:image/png;base64,","152959":"data:image/png;base64,","153019":"data:image/png;base64,","153046":"data:image/png;base64,","153106":"data:image/png;base64,","153144":"data:image/png;base64,","153203":"data:image/png;base64,","153225":"data:image/png;base64,","153239":"data:image/png;base64,","153304":"data:image/png;base64,","153352":"data:image/png;base64,","153423":"data:image/png;base64,","153500":"data:image/png;base64,","153509":"data:image/png;base64,","153541":"data:image/png;base64,","153705":"data:image/png;base64,","153733":"data:image/png;base64,","153900":"data:image/png;base64,","154039":"data:image/png;base64,","154237":"data:image/png;base64,","154310":"data:image/png;base64,","154342":"data:image/png;base64,","154414":"data:image/png;base64,","154437":"data:image/png;base64,","154537":"data:image/png;base64,","154612":"data:image/png;base64,","154651":"data:image/png;base64,","154805":"data:image/png;base64,","154923":"data:image/png;base64,","155039":"data:image/png;base64,","155457":"data:image/png;base64,"};
const DEFAULTS=[{"id":"breast","title":"Palpable Breast Abnormalities — Under 30","group":"Breast & Oncology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Palpable breast mass in patients under 30 → Breast ultrasound","choices":{"Lesion not visualized":"nv","Cystic lesion":"cy","Solid lesion":"so"}},"nv":{"text":"Perform mammogram if not already done","choices":{"Lesion visualized":"mvis","Lesion not visualized":"mnv"}},"mvis":{"end":"Follow abnormal mammogram algorithm"},"mnv":{"end":"Palpation-guided biopsy OR repeat clinical examination every 3–6 months ± ultrasound for 1–2 years; excisional biopsy if enlargement"},"cy":{"text":"Cystic lesion on ultrasound","choices":{"Asymptomatic simple cyst (BI-RADS 2)":"asym","Symptomatic simple cyst (BI-RADS 2)":"sym","Not simple cyst / complex or partially cystic mass":"cat"}},"asym":{"end":"Clinical follow-up"},"sym":{"end":"Therapeutic aspiration"},"so":{"text":"Solid lesion","choices":{"BI-RADS 1 or 2":"cl","BI-RADS 3":"f3","BI-RADS 4 or 5":"bx"}},"cat":{"text":"Classify non-simple cyst","choices":{"BI-RADS 3":"f3","BI-RADS 4 or 5":"bx"}},"cl":{"end":"Clinical follow-up"},"f3":{"end":"Follow-up ultrasound every 6–12 months for 2 years; biopsy if enlargement"},"bx":{"text":"Ultrasound-guided fine-needle aspiration or core needle biopsy","choices":{"Benign and concordant":"ben","Atypia or discordant":"exc","Malignant":"mal"}},"ben":{"end":"Follow up in 6–12 months with repeat ultrasound"},"exc":{"end":"Excision"},"mal":{"end":"Appropriate treatment"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"biliary","title":"Suspected Choledocholithiasis","group":"Gastroenterology & Hepatology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"s":{"text":"Suspected choledocholithiasis (RUQ pain and elevated liver enzymes, primarily cholestatic). CBD stone on imaging OR acute cholangitis OR bilirubin >4 mg/dL AND dilated CBD?","choices":{"Yes":"hi","No":"mid"}},"hi":{"text":"High probability CBD stone. Acute cholangitis or ongoing biliary obstruction with acute pancreatitis?","choices":{"Yes":"pre","No":"elect"}},"pre":{"end":"Preoperative ERCP followed by cholecystectomy"},"elect":{"end":"Preoperative ERCP and elective cholecystectomy OR cholecystectomy with intraoperative CBD exploration / intraoperative ERCP / postoperative ERCP"},"mid":{"text":"Abnormal liver biochemical tests OR age >55 years OR dilated CBD on imaging?","choices":{"Yes":"mr","No":"stones"}},"mr":{"text":"Intermediate probability: MRCP or EUS (cholecystectomy with IOC/IOUS is an alternative). CBD stone visualized?","choices":{"Yes":"elect","No":"chole"}},"stones":{"text":"Gallstones or sludge on ultrasound or cross-sectional imaging?","choices":{"Yes":"chole","No":"low"}},"chole":{"end":"Cholecystectomy"},"low":{"end":"Low probability of CBD stone — evaluate for alternative etiologies"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified","sourceImages":["154437"]},{"id":"pe","title":"Low-Probability Pulmonary Embolism — Nonpregnant Adults","group":"Pulmonology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Low pretest probability of pulmonary embolism (e.g., Wells score <2). Can PERC be applied?","choices":{"Yes":"perc","No":"dd"}},"perc":{"text":"All 8 PERC criteria fulfilled? Age <50; HR <100; SpO₂ >95%; no hemoptysis; no estrogen; no prior DVT/PE; no unilateral leg swelling; no surgery/trauma requiring hospitalization in previous 4 weeks","choices":{"Yes":"excluded","No":"dd"}},"dd":{"text":"Measure sensitive D-dimer (fibrinogen-equivalent units)","choices":{"<500 ng/mL":"excluded","≥500 ng/mL":"ct"}},"excluded":{"end":"Pulmonary embolism sufficiently excluded — no further testing required"},"ct":{"text":"Is CT pulmonary angiography feasible?","choices":{"Yes":"ctpa","No":"vq"}},"ctpa":{"text":"CT pulmonary angiography result","choices":{"Positive":"diagnosed","Negative":"excluded","Inconclusive":"vq"}},"vq":{"text":"Is ventilation/perfusion scanning feasible?","choices":{"Yes":"vqr","No":"further"}},"vqr":{"text":"Ventilation/perfusion scan: normal probability result?","choices":{"Yes":"excluded","No":"further"}},"diagnosed":{"end":"Pulmonary embolism diagnosed"},"further":{"end":"Further testing warranted"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"fissure","title":"Symptomatic Anal Fissure","group":"General Surgery","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"s":{"text":"Symptomatic anal fissure — typical posterior/anterior location without Crohn symptoms?","choices":{"Yes":"med","No":"gi"}},"med":{"text":"Four weeks: topical nifedipine or nitroglycerin, topical analgesic, stool softener, sitz bath and fiber. Symptoms persist?","choices":{"Yes":"med2","No":"done"}},"med2":{"text":"Four additional weeks of medical therapy. Symptoms persist?","choices":{"Yes":"scope","No":"done"}},"scope":{"text":"Endoscopy: Crohn disease?","choices":{"Yes":"gi","No":"surgery"}},"surgery":{"text":"Does patient desire surgical therapy?","choices":{"Yes":"colorectal","No":"alternate"}},"colorectal":{"text":"Refer to colorectal surgery. High risk of incontinence (multiparous women, older patients)?","choices":{"Yes":"botox","No":"lis"}},"botox":{"end":"Botulinum toxin injection OR anal advancement flap"},"lis":{"end":"Lateral internal sphincterotomy"},"alternate":{"end":"Alternate topical vasodilator: nitroglycerin after nifedipine, or nifedipine after nitroglycerin; OR second-line topical diltiazem/bethanechol or oral nifedipine/diltiazem; reassess continued symptoms"},"gi":{"end":"Refer to gastroenterology"},"done":{"end":"Symptoms resolved — continue supportive care"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified","sourceImages":["154651","154805"]},{"id":"preganemia","title":"Evaluation and Treatment of Anemia in Pregnancy","group":"Obstetrics & Gynecology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Initial CBC: unexplained anemia, microcytosis or other concern for iron deficiency?","choices":{"Yes":"iron","No":"repeat"}},"iron":{"text":"Iron studies (ferritin often sufficient). Are iron stores adequate?","choices":{"Yes":"other","No":"treat"}},"repeat":{"end":"Repeat CBC at 24–28 weeks gestation; obtain iron studies if new anemia develops"},"other":{"end":"Evaluate and treat other causes of anemia; repeat CBC at 24–28 weeks; iron studies if new anemia"},"treat":{"end":"Treat with iron; repeat CBC and reticulocyte count in 2–3 weeks; address causes of iron deficiency. Reference: first/third trimester Hb <11 g/dL, second trimester Hb <10.5 g/dL; ferritin <30 ng/mL supports deficiency. Oral iron usually first trimester; consider IV iron in second/third trimester for Hb <10, intolerance, malabsorption, oral failure or >30 weeks. Severe symptomatic anemia / compromise may require transfusion assessment."}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"head","title":"CT Head After Injury — Age 16+","group":"Emergency Medicine","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Person aged 16+ with head injury: GCS ≤12 initially; GCS <15 at 2 hours; suspected open/depressed fracture; basal skull signs; post-traumatic seizure; focal neurological deficit; >1 vomiting episode?","choices":{"Yes":"ct1","No":"loc"}},"ct1":{"end":"CT head within 1 hour of identifying any listed risk factor; provisional written radiology report within 1 hour of scan"},"loc":{"text":"Loss of consciousness or amnesia since head injury?","choices":{"Yes":"risk","No":"anti"}},"risk":{"text":"Age ≥65; bleeding/clotting disorder; dangerous mechanism; >30 minutes retrograde amnesia?","choices":{"Yes":"ct8","No":"anti"}},"ct8":{"end":"CT head within 8 hours of injury, or within 1 hour if presenting >8 hours after injury; report within 1 hour"},"anti":{"text":"Taking anticoagulant (VKA/DOAC/heparin/LMWH) or antiplatelet (excluding aspirin monotherapy)?","choices":{"Yes":"consider","No":"none"}},"consider":{"end":"Consider CT head within 8 hours of injury, or within 1 hour if presenting >8 hours after injury; report within 1 hour"},"none":{"end":"CT head scan not needed by this algorithm"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"dialysis","title":"CKD Hemodialysis — Routine Laboratory Follow-up","group":"Nephrology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"s":{"text":"Routine lab follow-up organized by frequency (CHI guideline image)","choices":{"Baseline":"base","Monthly":"month","Every 3 months":"q3","Every 6 months":"q6","Annually":"annual"}},"base":{"end":"All baseline investigations performed once at first visit"},"month":{"end":"CBC; ferritin; transferrin saturation; serum creatinine; BUN pre/post dialysis; sodium; potassium; calcium; bicarbonate; phosphorus; ALT; ALP; albumin; INR"},"q3":{"end":"Parathyroid hormone (PTH); AST"},"q6":{"end":"HCV antibody; HBsAg; HBsAb; HBcAb; fasting blood glucose; lipid profile; vitamin D; uric acid; MRSA screening"},"annual":{"end":"HIV combination test; vitamin B12; folic acid"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified","sourceImages":["155039"]},{"id":"thyroid","title":"Thyroid Nodule — TSH and TI-RADS","group":"Endocrinology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Thyroid nodule → TSH level","choices":{"Low TSH":"scan","Normal or high TSH":"us"}},"scan":{"text":"Radionuclide thyroid scan","choices":{"Hyperfunctioning hot nodule":"hot","Nonfunctioning cold nodule":"us"}},"hot":{"end":"Radioiodine ablation, surgery or antithyroid medication (as clinically indicated)"},"us":{"text":"Ultrasound → TI-RADS score","choices":{"TR1 score 0":"tr1","TR2 score 2":"tr2","TR3 score 3":"tr3","TR4 score 4–6":"tr4","TR5 score ≥7":"tr5"}},"tr1":{"end":"Benign — no FNA"},"tr2":{"end":"Not suspicious — no FNA"},"tr3":{"text":"Mildly suspicious — size?","choices":{"≥2.5 cm":"fna","≥1.5 to <2.5 cm":"fu135","<1.5 cm":"no"}},"tr4":{"text":"Moderately suspicious — size?","choices":{"≥1.5 cm":"fna","≥1 to <1.5 cm":"fu1235","<1 cm":"no"}},"tr5":{"text":"Highly suspicious — size?","choices":{"≥1 cm":"fna","≥0.5 to <1 cm":"fu5","<0.5 cm":"no"}},"fna":{"end":"Fine-needle aspiration (FNA)"},"fu135":{"end":"Ultrasound follow-up at 1, 3 and 5 years; no FNA"},"fu1235":{"end":"Ultrasound follow-up at 1, 2, 3 and 5 years; no FNA"},"fu5":{"end":"Ultrasound follow-up yearly for 5 years; no FNA"},"no":{"end":"No FNA at this size threshold"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"fib4","title":"Liver Fibrosis Assessment — FIB-4","group":"Gastroenterology & Hepatology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Clinical signs of advanced liver disease or cirrhosis (viral hepatitis, etc.)?","choices":{"Yes":"hepat","No":"risk"}},"risk":{"text":"Risk of chronic liver/metabolic dysfunction (metabolic syndrome, alcohol use, family history)?","choices":{"Yes":"labs","No":"low"}},"labs":{"text":"Obtain AST, ALT, GGT, ALP and platelets → calculate FIB-4 (age × AST)/(platelets × √ALT)","choices":{"FIB-4 <1.3":"low","FIB-4 >1.3":"hepat"}},"low":{"end":"Low-risk lifestyle modification; FibroScan not indicated on this depicted pathway"},"hepat":{"end":"Intermediate/high risk — hepatology referral and liver stiffness by transient elastography (FibroScan)"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"torsion","title":"Management After Detorsion of Ovarian Torsion","group":"Obstetrics & Gynecology","description":"Adult patient with confirmed adnexal torsion after operative detorsion.","kind":"flow","nodes":{"meno":{"text":"Is the patient premenopausal?","choices":{"Yes":"viable","No":"remove"}},"viable":{"text":"Is the ovary viable after detorsion and clinical assessment?","choices":{"Yes":"malignancy","No":"remove"}},"malignancy":{"text":"Is there concern for malignancy?","choices":{"Yes":"remove","No":"mass"}},"mass":{"text":"Is there a benign mass or large cyst?","choices":{"Yes":"cyst","No":"observe"}},"cyst":{"end":"Consider ovarian-sparing cystectomy when feasible; cyst drainage may be considered selectively. Preserve ovarian tissue where appropriate."},"observe":{"end":"Detorsion alone may be sufficient; no additional ovarian procedure routinely required."},"remove":{"end":"Consider salpingo-oophorectomy according to menopausal status, suspicion of malignancy and intraoperative findings. In premenopausal patients, apparent dark coloration alone does not establish nonviability; ovarian preservation is generally preferred when feasible."}},"start":"meno","source":"User-provided detorsion flowchart; ACOG Adnexal Torsion guidance (context-dependent)"},{"id":"ectopic","title":"Choosing Treatment for Ectopic Pregnancy","group":"Obstetrics & Gynecology","description":"Triage between emergency surgery, medical treatment and selected expectant management.","kind":"flow","nodes":{"emergency":{"text":"Hemodynamic instability, peritoneal signs, or suspected/confirmed tubal rupture?","choices":{"Yes":"surgery","No":"location"}},"location":{"text":"Is tubal ectopic pregnancy confirmed, with a viable intrauterine pregnancy excluded?","choices":{"Yes":"hcg","No":"verify"}},"hcg":{"text":"Is serum β-hCG ≥ 5,000 IU/L, or is embryonic cardiac activity seen on transvaginal ultrasound?","choices":{"Yes":"surgicalReview","No":"follow"}},"follow":{"text":"Can the patient comply with close follow-up and emergency return precautions?","choices":{"Yes":"contra","No":"surgery"}},"contra":{"text":"Any contraindication to methotrexate (e.g., coexisting viable intrauterine pregnancy, breastfeeding, significant hepatic/renal/hematologic dysfunction, immunodeficiency, active pulmonary or peptic ulcer disease)?","choices":{"Yes":"surgery","No":"options"}},"options":{"text":"Is the patient asymptomatic, stable, and eligible for expectant management under local guideline thresholds?","choices":{"Yes":"expectant","No":"mtx"}},"verify":{"end":"Confirm pregnancy location and viability with appropriate serial β-hCG and transvaginal ultrasound. Exclude a viable intrauterine pregnancy before methotrexate. Escalate immediately if unstable."},"surgery":{"end":"Urgent gynecology assessment for surgical management; resuscitate as needed. Surgical choice depends on stability, tubal status, fertility wishes and contralateral tube."},"surgicalReview":{"end":"Specialist surgical assessment is generally favored with high β-hCG or visible fetal cardiac activity; methotrexate success is lower. Discuss individualized options and local criteria."},"mtx":{"end":"Methotrexate may be offered if all eligibility criteria are met. Obtain baseline CBC, renal and liver tests; ensure day 4/day 7 β-hCG monitoring and follow until resolution."},"expectant":{"end":"Selected stable, pain-free patients with low and declining β-hCG may be managed expectantly with strict serial β-hCG follow-up and emergency precautions."}},"start":"emergency","source":"User-provided ectopic pregnancy flowchart; NICE NG126"},{"id":"hypertension","title":"Diagnostic Evaluation of Hypertension in Pregnancy / Postpartum","group":"Obstetrics & Gynecology","description":"Screen for gestational hypertension, preeclampsia and severe features.","kind":"flow","nodes":{"severe":{"text":"Severe hypertension (SBP ≥160 or DBP ≥110 mmHg), seizure, pulmonary edema, or other emergency features?","choices":{"Yes":"urgent","No":"timing"}},"timing":{"text":"Is this new hypertension at ≥20 weeks of pregnancy or during the postpartum period?","choices":{"Yes":"protein","No":"chronic"}},"protein":{"text":"Is significant proteinuria present?","choices":{"Yes":"features","No":"organ"}},"features":{"text":"Any severe features (platelets <100,000/µL, creatinine >1.1 mg/dL or doubled baseline, liver enzymes ≥2× upper limit, pulmonary edema, persistent severe headache/visual symptoms)?","choices":{"Yes":"severePre","No":"pre"}},"organ":{"text":"Any new maternal organ dysfunction or severe clinical features despite absent proteinuria?","choices":{"Yes":"severePre","No":"gestational"}},"urgent":{"end":"Emergency obstetric assessment. Treat persistent severe-range BP promptly, assess for preeclampsia/eclampsia and maternal-fetal compromise; magnesium sulfate when indicated."},"chronic":{"end":"Consider chronic hypertension if predating pregnancy or occurring before 20 weeks. Assess for superimposed preeclampsia when new proteinuria or organ dysfunction develops. Postpartum hypertension requires separate clinical evaluation."},"severePre":{"end":"Preeclampsia with severe features is possible even without proteinuria. Urgent inpatient obstetric assessment, labs, fetal evaluation if pregnant, and management per gestational age."},"pre":{"end":"Probable preeclampsia without severe features; confirm BP and proteinuria, monitor maternal labs and fetal well-being, and determine surveillance/delivery timing."},"gestational":{"end":"Possible gestational hypertension if BP ≥140/90 after 20 weeks without proteinuria or organ dysfunction. Repeat BP and evaluate CBC, creatinine, liver enzymes and urine protein."}},"start":"severe","source":"User-provided hypertension flowchart; ACOG Practice Bulletin 222 / NICE NG133"},{"id":"adnexal-pre","title":"Adnexal Mass in Premenopausal Patients","group":"Obstetrics & Gynecology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"urgent":{"text":"Acute severe pain, suspected torsion, rupture or hemodynamic instability?","choices":{"Yes":"urgentEnd","No":"risk"}},"risk":{"text":"Ultrasound O-RADS category?","choices":{"O-RADS 5":"high","O-RADS 4":"intermediate","O-RADS 3":"low","O-RADS 2":"benign","Unknown":"unknown"}},"high":{"end":"High malignancy risk: urgent specialist gynecologic oncology assessment and appropriate surgical planning."},"intermediate":{"end":"Intermediate risk: specialist evaluation, tumor markers where appropriate, and individualized surgery versus short-interval imaging."},"low":{"end":"Low risk: structured ultrasound surveillance or specialist review according to size, morphology and symptoms."},"benign":{"end":"Almost certainly benign lesion: manage according to cyst type, size, symptoms and ultrasound criteria; many require no intervention."},"urgentEnd":{"end":"Urgent gynecologic evaluation; do not delay suspected torsion management for routine risk scoring."},"unknown":{"end":"Obtain complete transvaginal ultrasound characterization and formal O-RADS category before deciding surveillance versus surgery."}},"start":"urgent","source":"User-provided adnexal mass flowchart; ACR O-RADS","sourceImages":["151611"]},{"id":"adnexal-post","title":"Adnexal Mass in Postmenopausal Patients","group":"Obstetrics & Gynecology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"risk":{"text":"Ultrasound O-RADS category?","choices":{"O-RADS 5":"high","O-RADS 4":"intermediate","O-RADS 3":"low","O-RADS 2":"benign","Unknown":"unknown"}},"high":{"end":"High-risk mass: gynecologic oncology assessment and surgical planning."},"intermediate":{"end":"Intermediate-risk mass: assess symptoms, CA-125, morphology and risk factors; refer for specialist management."},"low":{"end":"Low-risk mass: specialist-directed follow-up ultrasound and CA-125 as appropriate."},"benign":{"end":"Almost certainly benign mass: assess size, cyst morphology and symptoms; observation may be appropriate."},"unknown":{"end":"Obtain standardized ultrasound risk characterization; check CA-125 where indicated."}},"start":"risk","source":"User-provided postmenopausal mass flowchart; ACR O-RADS / RCOG","sourceImages":["151700"]},{"id":"pelvic-preg","title":"Pelvic Pain in Pregnancy","group":"Obstetrics & Gynecology","description":"Emergency screening and differential diagnosis.","kind":"flow","nodes":{"shock":{"text":"Hemodynamic instability, syncope, peritoneal signs, or major bleeding?","choices":{"Yes":"emergency","No":"bleed"}},"bleed":{"text":"Is vaginal bleeding present?","choices":{"Yes":"bleeding","No":"nobleeding"}},"bleeding":{"text":"Is pregnancy ≥20 weeks?","choices":{"Yes":"late","No":"early"}},"nobleeding":{"text":"Regular uterine contractions?","choices":{"Yes":"labor","No":"other"}},"emergency":{"end":"Immediate emergency obstetric assessment and resuscitation. Consider ruptured ectopic pregnancy, placental abruption, uterine rupture and hemorrhage depending on gestational age."},"late":{"end":"Evaluate placenta, fetal status, labor and abruption; urgent obstetric assessment as indicated."},"early":{"end":"Exclude ectopic pregnancy and early pregnancy loss with ultrasound and β-hCG as appropriate."},"labor":{"end":"Assess labor, gestational age, cervix, fetal status and preterm labor risk."},"other":{"end":"Consider ovarian torsion, appendicitis, urinary pathology, infection and pelvic girdle pain; investigate according to clinical findings."}},"start":"shock","source":"User-provided pelvic pain flowcharts"},{"id":"pph","title":"Postpartum Hemorrhage – Initial Approach","group":"Obstetrics & Gynecology","description":"Immediate recognition, resuscitation and 4-T assessment.","kind":"flow","nodes":{"pph":{"text":"Is postpartum hemorrhage suspected or quantified blood loss concerning?","choices":{"Yes":"resuscitate","No":"routine"}},"resuscitate":{"text":"Is uterine atony suspected?","choices":{"Yes":"atony","No":"other"}},"atony":{"end":"Activate obstetric hemorrhage response. Uterine massage, oxytocin, IV access, fluids/blood products as indicated, early tranexamic acid within 3 hours, and escalate uterotonics/procedures per protocol. Evaluate all 4 Ts."},"other":{"end":"Identify and treat the 4 Ts: Trauma (lacerations), Tissue (retained products), Thrombin (coagulopathy), and Tone (atony). Resuscitate concurrently and escalate rapidly."},"routine":{"end":"Continue postpartum surveillance and quantify blood loss; reassess immediately if bleeding or vital signs worsen."}},"start":"pph","source":"User-provided PPH flowchart; WHO PPH recommendations"},{"id":"abdominal","title":"Emergency Evaluation of Abdominal Pain","group":"Emergency Medicine","description":"Initial safety triage and focused diagnostic approach.","kind":"flow","nodes":{"unstable":{"text":"Shock, peritonitis, severe bleeding or other immediately life-threatening findings?","choices":{"Yes":"emergency","No":"preg"}},"preg":{"text":"Is pregnancy possible?","choices":{"Yes":"test","No":"focus"}},"test":{"text":"Pregnancy test positive?","choices":{"Yes":"pregEnd","No":"focus"}},"focus":{"text":"Is there focal peritoneal tenderness or strong suspicion of surgical abdomen?","choices":{"Yes":"surgical","No":"other"}},"emergency":{"end":"Immediate emergency resuscitation and surgical/obstetric assessment; targeted bedside imaging and labs should not delay definitive treatment."},"pregEnd":{"end":"Exclude ectopic pregnancy and pregnancy-related emergencies. Ultrasound and obstetric/gynecologic evaluation according to stability."},"surgical":{"end":"Urgent surgical evaluation and targeted imaging based on location and suspected appendicitis, obstruction, perforation, cholecystitis or other causes."},"other":{"end":"Evaluate gastrointestinal, urinary, gynecologic, metabolic and extra-abdominal causes; tailor testing to history, exam and risk factors."}},"start":"unstable","source":"User-provided abdominal pain flowchart"},{"id":"aub","title":"Abnormal Uterine Bleeding – Reproductive Age","group":"Obstetrics & Gynecology","description":"Nonpregnant reproductive-age patient with abnormal uterine bleeding.","kind":"flow","nodes":{"preg":{"text":"Has pregnancy been excluded and hemodynamic stability confirmed?","choices":{"Yes":"etiology","No":"urgent"}},"etiology":{"text":"Is a structural, infectious or endocrine cause identified?","choices":{"Yes":"treat","No":"risk"}},"treat":{"text":"Does bleeding resolve after treating the underlying cause?","choices":{"Yes":"done","No":"risk"}},"risk":{"text":"High thrombotic risk or estrogen contraindication?","choices":{"Yes":"nonestrogen","No":"options"}},"urgent":{"end":"Evaluate pregnancy and hemodynamic stability first. Severe acute bleeding requires urgent stabilization and assessment."},"done":{"end":"Continue routine follow-up and treat underlying condition."},"nonestrogen":{"end":"Consider levonorgestrel intrauterine system, appropriate progestins or NSAIDs if eligible. Tranexamic acid requires careful thrombosis risk review."},"options":{"end":"Options include levonorgestrel IUS, combined hormonal contraception, tranexamic acid, NSAIDs and progestins, individualized by contraindications and fertility goals."}},"start":"preg","source":"User-provided AUB flowchart; NICE NG88"},{"id":"contraceptive","title":"Unscheduled Bleeding with Contraceptives","group":"Obstetrics & Gynecology","description":"Bleeding during hormonal contraception or copper IUD use.","kind":"flow","nodes":{"exclude":{"text":"Have pregnancy, infection, device problems and concerning uterine/cervical pathology been assessed as appropriate?","choices":{"Yes":"type","No":"evaluate"}},"type":{"text":"Current contraception?","choices":{"Copper IUD":"copper","LNG-IUD":"lng","Implant":"implant","DMPA":"dmpa","Combined pill/patch/ring":"combined","Progestin-only pill":"pop"}},"evaluate":{"end":"Check adherence and medication interactions, exclude pregnancy when indicated, assess STI risk, and examine/investigate persistent or atypical bleeding."},"copper":{"end":"Check IUD placement when indicated; short NSAID course may help. Reassess persistent or unacceptable bleeding."},"lng":{"end":"Counsel that irregular bleeding often improves. Investigate persistent or new bleeding and discuss method change if unacceptable."},"implant":{"end":"Counsel and consider short-term treatment based on medical eligibility; bleeding may recur. Offer method change if unacceptable."},"dmpa":{"end":"Counsel and consider NSAIDs or a short hormonal course if medically eligible; reassess heavy/prolonged bleeding."},"combined":{"end":"Review adherence and formulation; a brief hormone-free interval may help selected continuous users, subject to regimen and contraceptive guidance."},"pop":{"end":"Review adherence and exclude other causes. Evidence for specific interventions is limited; consider alternative method if unacceptable."}},"start":"exclude","source":"User-provided contraceptive bleeding charts; CDC Selected Practice Recommendations"},{"id":"twins","title":"Route of Delivery in Diamniotic Twins","group":"Obstetrics & Gynecology","description":"Presentation, gestational age and obstetric expertise.","kind":"flow","nodes":{"first":{"text":"Is Twin A cephalic?","choices":{"Yes":"second","No":"cs"}},"second":{"text":"Is Twin B cephalic?","choices":{"Yes":"vaginal","No":"nonvertex"}},"nonvertex":{"text":"Is an experienced obstetrician available for second-twin breech delivery, and are gestation/estimated weights appropriate?","choices":{"Yes":"individual","No":"cs"}},"vaginal":{"end":"Planned vaginal birth may be appropriate if no obstetric contraindications and appropriate resources are available."},"individual":{"end":"Individualized planned vaginal delivery may be considered with skilled second-twin management and immediate cesarean capability. Avoid rigid weight thresholds without full assessment."},"cs":{"end":"Planned cesarean delivery is generally recommended when Twin A is non-cephalic or other contraindications prevent safe vaginal delivery."}},"start":"first","source":"User-provided twin delivery flowchart; NICE NG137"},{"id":"pelvic-child","title":"Acute Pelvic Pain – Premenarcheal Patient","group":"Obstetrics & Gynecology","description":"Pediatric pelvic pain differential including urgent surgical causes.","kind":"flow","nodes":{"unstable":{"text":"Hemodynamic instability, peritonitis or severe acute pain?","choices":{"Yes":"urgent","No":"trauma"}},"trauma":{"text":"History or findings of genital trauma?","choices":{"Yes":"traumaEnd","No":"obstruct"}},"obstruct":{"text":"Imperforate hymen or midline pelvic mass?","choices":{"Yes":"obstructEnd","No":"preg"}},"preg":{"text":"Is pregnancy possible based on a confidential, safeguarding-aware assessment?","choices":{"Yes":"pregTest","No":"flank"}},"pregTest":{"text":"Pregnancy test positive?","choices":{"Yes":"ectopic","No":"flank"}},"flank":{"text":"Flank pain, hematuria or urinary symptoms?","choices":{"Yes":"urinary","No":"rlq"}},"urinary":{"text":"Imaging or urine testing supports stone or UTI?","choices":{"Stone":"stone","UTI":"uti","Neither / unclear":"rlq"}},"rlq":{"text":"Right lower quadrant tenderness, guarding or adnexal abnormality?","choices":{"Yes":"surgical","No":"other"}},"urgent":{"end":"Immediate pediatric emergency and surgical/gynecologic evaluation; exclude ovarian torsion, appendicitis and other emergencies."},"traumaEnd":{"end":"Evaluate injury, bleeding and safeguarding needs with appropriately trained pediatric clinicians."},"obstructEnd":{"end":"Urgent pediatric gynecology assessment for possible obstructive genital tract anomaly, hematocolpos or hydrocolpos."},"ectopic":{"end":"Urgent pregnancy-location assessment; exclude ectopic pregnancy regardless of reported sexual history."},"stone":{"end":"Evaluate urolithiasis and urinary obstruction with age-appropriate imaging and urine testing."},"uti":{"end":"Assess for urinary tract infection; culture and treat based on symptoms and severity."},"surgical":{"end":"Urgent assessment for appendicitis and ovarian/adnexal torsion; a normal Doppler study does not fully exclude torsion."},"other":{"end":"Consider gastrointestinal, musculoskeletal, urinary and gynecologic causes; reassess if persistent or worsening symptoms."}},"start":"unstable","source":"User-provided premenarcheal pelvic pain flowchart; pediatric emergency assessment principles"},{"id":"pelvic-post","title":"Acute Pelvic Pain – Postmenarcheal Patient","group":"Obstetrics & Gynecology","description":"Adolescent pelvic pain including dysmenorrhea, PID, torsion and urinary/surgical causes.","kind":"flow","nodes":{"urgent":{"text":"Hemodynamic instability, peritonitis or severe acute pain?","choices":{"Yes":"emergency","No":"preg"}},"preg":{"text":"Pregnancy test positive?","choices":{"Yes":"pregnancy","No":"trauma"}},"trauma":{"text":"Genital trauma or assault suspected?","choices":{"Yes":"traumaEnd","No":"menstrual"}},"menstrual":{"text":"Pain typical of recurrent menstrual cramps without red flags?","choices":{"Yes":"dysmen","No":"pid"}},"pid":{"text":"Cervical motion, uterine or adnexal tenderness with clinical suspicion of PID?","choices":{"Yes":"pidEnd","No":"adnexal"}},"adnexal":{"text":"Adnexal mass, focal tenderness or ultrasound abnormality?","choices":{"Yes":"torsion","No":"rlq"}},"rlq":{"text":"RLQ tenderness, guarding or peritoneal signs?","choices":{"Yes":"appendix","No":"urinary"}},"urinary":{"text":"Flank pain, dysuria, hematuria or suprapubic tenderness?","choices":{"Yes":"urinaryEnd","No":"chronic"}},"chronic":{"text":"Recurrent cyclical pelvic pain or chronic dysmenorrhea?","choices":{"Yes":"endo","No":"other"}},"emergency":{"end":"Immediate emergency assessment for hemorrhage, ectopic pregnancy, torsion or acute surgical abdomen."},"pregnancy":{"end":"Evaluate pregnancy location, ectopic pregnancy and pregnancy-related complications urgently according to stability."},"traumaEnd":{"end":"Trauma care and confidential safeguarding assessment; offer specialist support."},"dysmen":{"end":"Likely primary dysmenorrhea if assessment supports it; investigate atypical, persistent or refractory pain."},"pidEnd":{"end":"Evaluate and treat suspected pelvic inflammatory disease promptly based on clinical criteria; test for sexually transmitted infections as indicated."},"torsion":{"end":"Urgent gynecology evaluation for torsion, cyst rupture, adnexal mass or neoplasm; ultrasound findings alone cannot reliably exclude torsion."},"appendix":{"end":"Urgent evaluation for appendicitis and other surgical pathology; select imaging appropriately."},"urinaryEnd":{"end":"Urinalysis/culture and assessment for UTI, pyelonephritis or urinary stones as clinically indicated."},"endo":{"end":"Consider endometriosis and secondary dysmenorrhea, particularly with persistent pain despite first-line treatment."},"other":{"end":"Reassess for gastrointestinal, urinary, infectious, musculoskeletal and functional causes; arrange follow-up and return precautions."}},"start":"urgent","source":"User-provided postmenarcheal pelvic pain flowchart; adolescent gynecology principles"},{"id":"pelvic-preg-bleeding","title":"Pelvic Pain in Pregnancy with Vaginal Bleeding","group":"Obstetrics & Gynecology","description":"Pregnant adolescent/adult with pelvic pain and bleeding: emergency differential.","kind":"flow","nodes":{"shock":{"text":"Shock, syncope, peritoneal signs or major ongoing bleeding?","choices":{"Yes":"resus","No":"age"}},"age":{"text":"Gestational age ≥20 weeks?","choices":{"Yes":"late","No":"early"}},"resus":{"end":"Emergency obstetric resuscitation and assessment. Exclude ruptured ectopic pregnancy, placental abruption and uterine rupture according to gestation."},"late":{"end":"Urgently assess placental abruption, labor, placenta-related bleeding and fetal condition; avoid digital examination until placenta previa is excluded when relevant."},"early":{"end":"Urgently exclude ectopic pregnancy and assess miscarriage with transvaginal ultrasound and quantitative β-hCG when indicated."}},"start":"shock","source":"User-provided pregnancy pelvic pain with bleeding chart"},{"id":"pelvic-preg-no-bleeding","title":"Pelvic Pain in Pregnancy without Vaginal Bleeding","group":"Obstetrics & Gynecology","description":"Contractions, infection, musculoskeletal and non-obstetric causes.","kind":"flow","nodes":{"urgent":{"text":"Severe pain, hemodynamic instability, fever with sepsis or peritonitis?","choices":{"Yes":"emergency","No":"contractions"}},"contractions":{"text":"Regular rhythmic uterine contractions?","choices":{"Yes":"gestation","No":"infection"}},"gestation":{"text":"Gestation ≥20 weeks?","choices":{"Yes":"labor","No":"early"}},"infection":{"text":"Fever, peritoneal signs or focal abdominal tenderness?","choices":{"Yes":"nonob","No":"pelvicgirdle"}},"pelvicgirdle":{"text":"Pain reproduced at sacroiliac/pelvic girdle examination?","choices":{"Yes":"girdle","No":"nonob"}},"emergency":{"end":"Urgent obstetric/emergency assessment; exclude surgical and pregnancy-related emergencies."},"labor":{"end":"Assess preterm or term labor, cervix and fetal status."},"early":{"end":"Assess early pregnancy complications, including pregnancy loss or ectopic pregnancy where location is not confirmed."},"nonob":{"end":"Investigate appendicitis, urinary infection/stones, ovarian torsion and other non-obstetric causes as appropriate."},"girdle":{"end":"Consider pregnancy-related pelvic girdle pain after excluding obstetric and surgical red flags."}},"start":"urgent","source":"User-provided pregnant pelvic pain without bleeding chart"},{"id":"cdc-bleeding","title":"CDC Management of Contraceptive-Related Bleeding","group":"Obstetrics & Gynecology","description":"Method-specific approach to unacceptable spotting or prolonged bleeding.","kind":"flow","nodes":{"exclude":{"text":"Have pregnancy, STI, thyroid/uterine pathology and device problems been considered where indicated?","choices":{"Yes":"method","No":"workup"}},"method":{"text":"Which contraceptive method?","choices":{"Copper IUD":"copper","LNG-IUD":"lng","Implant":"implant","DMPA injection":"dmpa","Continuous CHC":"chc"}},"workup":{"end":"Evaluate other causes of abnormal bleeding; discuss patient preferences and continuation versus removal."},"copper":{"end":"Short course NSAIDs (typically 5–7 days) may be considered if no contraindications; investigate persistent heavy bleeding."},"lng":{"end":"Reassurance and assessment of other causes; evidence does not support a specific routine medication for LNG-IUD bleeding. Offer removal if desired."},"implant":{"end":"Discuss temporary treatments such as NSAIDs, combined estrogen-containing treatment when eligible, or tamoxifen under appropriate protocols; bleeding may recur."},"dmpa":{"end":"Consider NSAIDs for spotting or short hormonal treatment for heavy/prolonged bleeding if medically eligible; reassess other causes."},"chc":{"end":"For eligible continuous/extended CHC users, a 3–4-day hormone-free interval may be considered, not in the first 21 days and not more than once per month."}},"start":"exclude","source":"User-provided CDC contraception flowchart; CDC US Selected Practice Recommendations 2024"},{"id":"birads","title":"BI-RADS Assessment Categories","group":"Breast & Oncology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","nodes":{"s":{"text":"BI-RADS assessment category","choices":{"0":"c0","1":"c1","2":"c2","3":"c3","4":"c4","5":"c5","6":"c6"}},"c0":{"end":"Incomplete — additional imaging and/or comparison with prior mammograms; likelihood N/A"},"c1":{"end":"Negative — routine mammography screening; essentially 0% likelihood of malignancy"},"c2":{"end":"Benign — routine mammography screening; essentially 0% likelihood of malignancy"},"c3":{"end":"Probably benign — short interval (6-month) follow-up; >0% to ≤2% likelihood"},"c4":{"text":"Suspicious — tissue diagnosis; >2% to <95% likelihood","choices":{"4A":"a","4B":"b","4C":"c"}},"a":{"end":"4A — Low suspicion: >2% to ≤10%"},"b":{"end":"4B — Moderate suspicion: >10% to ≤50%"},"c":{"end":"4C — High suspicion: >50% to <95%"},"c5":{"end":"Highly suggestive of malignancy — tissue diagnosis; ≥95% likelihood"},"c6":{"end":"Known biopsy-proven malignancy — surgical excision when clinically appropriate; likelihood N/A"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified","sourceImages":["154537"]},{"id":"bethesda","title":"Thyroid FNA — Bethesda Classification","group":"Endocrinology","description":"Transcribed and digitally redrawn from the originally uploaded image","kind":"flow","nodes":{"s":{"text":"Fine-needle aspiration → cytopathology Bethesda category","choices":{"I":"b1","II":"b2","III or IV":"b34","V":"b5","VI":"b6"}},"b1":{"end":"Nondiagnostic — repeat FNA in 6–12 weeks"},"b2":{"end":"Benign — ultrasound follow-up in 12–24 months"},"b34":{"text":"Category 3 or 4: suspicious ultrasound features?","choices":{"Yes":"lob","No":"size"}},"size":{"text":"Nodule ≥4 cm?","choices":{"Yes":"lob","No":"molecular"}},"lob":{"end":"Refer for diagnostic lobectomy"},"molecular":{"end":"Consider molecular testing"},"b5":{"end":"Suspicious for malignancy — refer for surgical excision"},"b6":{"end":"Malignant — refer for surgical excision"}},"start":"s","source":"Original user-uploaded clinical diagram — transcription; clinical currency not independently verified"},{"id":"polyneuropathy","title":"Diagnostic Approach to Polyneuropathy","group":"Neurology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","start":"start","nodes":{"start":{"text":"Symptoms suggestive of polyneuropathy","choices":{"Hyporeflexia, sensory loss, atrophy or weakness":"hypo","Hyperreflexia, increased tone":"hyper"}},"hyper":{"end":"Consider central process (eg, spinal cord disease)"},"hypo":{"text":"EMG assessment","choices":{"Polyradiculopathy, plexopathy or mononeuropathy multiplex":"multi","Normal EMG":"normal","Axonal physiology":"axonal","Demyelinating physiology":"demyel","Mixed pattern":"mixed"}},"multi":{"end":"Work-up as appropriate, including imaging studies (radiculopathy and plexopathy) and nerve biopsy/serologic studies (mononeuritis multiplex)"},"normal":{"end":"Observe for progression; repeat EMG; skin biopsy for evaluation of small fibers; autonomic testing. Consider work-up as for axonal polyneuropathy."},"axonal":{"text":"Review toxin and drug exposures. Initial tests: B12, TSH, glucose, glycohemoglobin, ANA, ESR, SPEP and UPEP. Assess family history.","choices":{"If initial work-up is negative":"axonal2"}},"axonal2":{"end":"Consider urine heavy metals, urine porphyrins, rheumatoid factor, Sjögren’s testing, Lyme antibody, HIV, Hu antibody, methylmalonic acid, homocysteine, and hepatitis B and C."},"demyel":{"text":"Demyelinating physiology on EMG","choices":{"Hereditary features on EMG":"hereditary","Acquired features on EMG; no family history":"acquired"}},"hereditary":{"end":"Consider Charcot-Marie-Tooth disease type 1. Evaluate family members; genetic testing."},"acquired":{"text":"Evaluate SPEP, UPEP, hepatitis B and C, HIV, lumbar puncture, GM1/anti-MAG antibodies.","choices":{"Consider treatment":"treatment"}},"treatment":{"end":"Consider treatment for CIDP with steroids, plasmapheresis or IVIG."},"mixed":{"text":"Work-up as for demyelinating physiology","choices":{"If negative":"mixed2"}},"mixed2":{"end":"Consider peripheral nerve biopsy and axonal polyneuropathy work-up."}},"sourceImages":["155457"]},{"id":"uploaded-151525","title":"Ruptured Ovarian Cyst — Management","group":"Obstetrics & Gynecology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["151525"],"nodes":{"s":{"text":"Patient with suspected ruptured ovarian cyst: assess hemodynamic stability and pregnancy status","choices":{"Unstable / significant bleeding":"urgent","Stable":"stable"}},"urgent":{"end":"Urgent resuscitation and gynecologic/surgical assessment"},"stable":{"text":"Assess symptoms, ultrasound findings and bleeding; clinical risk warrants intervention?","choices":{"Yes":"surgery","No":"observe"}},"surgery":{"end":"Gynecologic surgical evaluation as clinically indicated"},"observe":{"end":"Conservative management, analgesia and follow-up as appropriate"}},"start":"s"},{"id":"uploaded-151957","title":"MRI Indications for Low Back Pain","group":"Orthopedics & Spine","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["151957","152755"],"nodes":{"s":{"text":"Low back pain: red flags (serious pathology, neurological deficit)?","choices":{"Yes":"urgent","No":"duration"}},"urgent":{"end":"Urgent assessment; MRI and/or radiographs based on clinical indication"},"duration":{"text":"Symptom duration","choices":{"<6 weeks":"short","6–12 weeks":"mid",">12 weeks":"long"}},"short":{"end":"Conservative management when no red flags"},"mid":{"text":"Completed conservative treatment?","choices":{"No":"con","Yes":"disc"}},"long":{"text":"Disc herniation criteria met?","choices":{"Yes":"mri","No":"con"}},"disc":{"text":"Disc herniation criteria met?","choices":{"Yes":"mri","No":"con"}},"mri":{"end":"MRI may be considered based on clinical findings"},"con":{"end":"Continue conservative management; assess yellow flags and consider multidisciplinary treatment"}},"start":"s"},{"id":"uploaded-152238","title":"Haemorrhoids — Evidence-Based Treatment","group":"General & Colorectal Surgery","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["152238"],"sections":[["Hemorrhoids",[["Grade I","Bleeding without prolapse"],["Grade II","Prolapse reduces spontaneously"],["Grade III","Requires manual reduction"],["Grade IV","Irreducible prolapse"],["Management overview","Lifestyle and fiber for all grades; office-based and surgical interventions according to grade, symptoms and clinical assessment"]]]]},{"id":"uploaded-152356","title":"Pneumonia Admission — Adults and Children","group":"Pulmonology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["152356"],"sections":[["Pneumonia severity / admission",[["Adults","CURB-65: confusion, urea >7 mmol/L, respiratory rate ≥30/min, low blood pressure, age ≥65 years"],["Severity","Higher score suggests greater need for hospital evaluation; use clinical judgment and local criteria"],["Children","Respiratory distress, sustained hypoxemia, young age with suspected bacterial CAP, virulent pathogen or inadequate home monitoring favor admission"]]]]},{"id":"uploaded-152522","title":"Tonsillectomy — Surgical Indications","group":"ENT","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["152522"],"nodes":{"s":{"text":"Tonsillectomy — recurrent documented infection or other indication?","choices":{">6 culture-confirmed streptococcal episodes in 1 year":"review","5 episodes/year for 2 consecutive years":"review","≥3 infections/year for 3 consecutive years":"review","Refractory chronic/recurrent tonsillitis with carrier state":"review"}},"review":{"end":"Consider ENT surgical assessment; verify episode documentation, severity, treatment and applicable guideline criteria"}},"start":"s"},{"id":"uploaded-152621","title":"Septoplasty — Indications and Contraindications","group":"ENT","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["152621"],"nodes":{"s":{"text":"Septoplasty: clinically significant septal deviation / nasal obstruction or another documented surgical indication?","choices":{"Yes":"trial","No":"not"}},"trial":{"text":"Failed appropriate conservative treatment, or a documented exception (trauma, surgical access, recurrent epistaxis)?","choices":{"Yes":"candidate","No":"medical"}},"candidate":{"end":"Consider septoplasty; correlate symptoms and objective findings; review recent imaging when indicated"},"medical":{"end":"Document conservative management first where appropriate"},"not":{"end":"Not indicated for asymptomatic deviation, isolated allergic rhinitis or uncomplicated snoring"}},"start":"s"},{"id":"uploaded-152700","title":"Myringotomy and Grommet Tubes — OME","group":"ENT","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["152700"],"nodes":{"s":{"text":"Otitis media with effusion (OME): consideration of myringotomy / grommet tube","next":"t"},"t":{"text":"Documented medical treatment / observation for approximately 3 months?","choices":{"No":"no","Yes":"yes"}},"no":{"end":"Continue appropriate conservative management / reassess"},"yes":{"text":"Document supporting findings","choices":{"Conductive hearing loss on pure-tone audiogram":"pta","Type B tympanogram":"tymp"}},"pta":{"end":"Audiometric finding supports consideration of intervention"},"tymp":{"end":"Flat Type B tympanogram supports middle-ear effusion assessment"}},"start":"s"},{"id":"uploaded-152959","title":"Multiple Sclerosis — Medication Reference 1","group":"Neurology & Immunology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["152959"],"sections":[["Multiple sclerosis therapies",[["Gilenya (fingolimod)","0.5 mg orally once daily for patients >40 kg; pediatric ≤40 kg 0.25 mg daily (source)"],["Mayzent (siponimod)","Dose titration required; maintenance 2 mg daily for eligible genotypes"],["Ocrevus (ocrelizumab)","Initial 300 mg IV, repeat after 2 weeks; then 600 mg IV every 6 months"]]]]},{"id":"uploaded-153019","title":"Multiple Sclerosis — Medication Reference 2","group":"Neurology & Immunology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153019"],"sections":[["Multiple sclerosis",[["Lemtrada (alemtuzumab)","12 mg IV daily ×5 days; second course 12 mg daily ×3 days 12 months later"],["Kesimpta (ofatumumab)","20 mg SC weeks 0, 1, 2; then every month from week 4"],["Mavenclad (cladribine)","Weight-based short-course tablets in years 1 and 2"],["Tysabri (natalizumab)","300 mg IV every 4 weeks"]]]]},{"id":"uploaded-153046","title":"Multiple Sclerosis — Medication Reference 3","group":"Neurology & Immunology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153046"],"sections":[["Multiple sclerosis",[["Fampyra (fampridine)","10 mg orally twice daily"],["Glatiramer acetate","40 mg SC three times weekly, ≥48 hours apart"],["Aubagio (teriflunomide)","7 or 14 mg orally daily"],["Tecfidera (dimethyl fumarate)","120 mg twice daily ×7 days, then 240 mg twice daily"],["Avonex (interferon beta-1a)","IM injection once weekly"]]]]},{"id":"uploaded-153106","title":"Biologic and Immunomodulator Medications — Reference 1","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153106"],"sections":[["Immunomodulators",[["Betaseron (interferon beta-1b)","SC every other day; verify product and strength"],["Rebif (interferon beta-1a)","SC three times weekly; pack count varies by strength"],["Dupixent (dupilumab)","Loading and maintenance depend on indication, age and weight; source shows 600 mg loading and 300 mg every 2 weeks"]]]]},{"id":"uploaded-153144","title":"Biologic and Immunomodulator Medications — Reference 2","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153144"],"sections":[["Biologics",[["Skyrizi (risankizumab)","Psoriasis: 150 mg SC at weeks 0 and 4, then every 12 weeks; Crohn dosing differs"],["Cosentyx (secukinumab)","Psoriasis: 300 mg SC weekly at weeks 0–4, then every 4 weeks; other indications vary"]]]]},{"id":"uploaded-153203","title":"Biologic and Immunomodulator Medications — Reference 3","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153203"],"sections":[["Biologics and oral immune therapies",[["Taltz (ixekizumab)","Psoriasis: 160 mg SC initially, then 80 mg every 2 weeks through week 12, then every 4 weeks"],["Xeljanz (tofacitinib)","RA source: 5 mg orally twice daily or XR 11 mg daily; UC dosing differs"]]]]},{"id":"uploaded-153225","title":"Biologic and Immunomodulator Medications — Reference 4","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153225"],"sections":[["Immune therapies",[["Rinvoq (upadacitinib)","RA 15 mg orally daily; UC induction/maintenance varies"],["Olumiant (baricitinib)","Verify indication and dose"],["Arava (leflunomide)","RA source: loading 100 mg daily ×3 days, then 10–20 mg daily"],["Nucala (mepolizumab)","100 mg SC every 4 weeks for severe eosinophilic asthma; EGPA regimen 300 mg every 4 weeks"]]]]},{"id":"uploaded-153239","title":"Biologic and Immunomodulator Medications — Reference 5","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153239"],"sections":[["Immune therapies",[["Rinvoq (upadacitinib)","Source repeats information from previous image"],["Olumiant (baricitinib)","Source repeats information from previous image"],["Arava (leflunomide)","Source repeats information from previous image"],["Nucala (mepolizumab)","Source repeats information from previous image"]]]]},{"id":"uploaded-153304","title":"Biologic and Immunomodulator Medications — Reference 6","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153304"],"sections":[["Immune therapies",[["Rinvoq (upadacitinib)","RA: 15 mg orally daily; UC: source lists 45 mg daily induction 8 weeks, then 15 or 30 mg daily"],["Olumiant (baricitinib)","Dosing and indication require individual verification"],["Arava (leflunomide)","Source: 100 mg daily for 3 days, then 10–20 mg daily"],["Nucala (mepolizumab)","100 mg SC every 4 weeks; EGPA 300 mg SC every 4 weeks"]]]]},{"id":"uploaded-153352","title":"Biologic and Immunomodulator Medications — Reference 7","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153352"],"sections":[["Immune therapies",[["Stelara (ustekinumab)","Plaque psoriasis weight-based 45 or 90 mg at weeks 0,4 then every 12 weeks; Crohn IV induction weight-based then SC maintenance"],["Otezla (apremilast)","Titration over days 1–5, then 30 mg orally twice daily"],["Humira (adalimumab), Crohn","Source: 160 mg day 1, 80 mg day 15, then 40 mg every other week"]]]]},{"id":"uploaded-153423","title":"Rheumatoid Arthritis — DAS28 and Treatment","group":"Rheumatology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153423"],"sections":[["Rheumatoid arthritis",[["Clinical assessment","Document DAS28 and response to conventional DMARDs"],["Conventional DMARDs","Methotrexate, hydroxychloroquine, leflunomide, sulfasalazine"],["Advanced therapies listed","Sarilumab, etanercept, infliximab, certolizumab, golimumab, abatacept, tofacitinib, baricitinib, rituximab, tocilizumab"],["DAS28 <2.6","Remission"],["DAS28 2.6–3.2","Low disease activity"],["DAS28 >3.2–5.1","Moderate activity"],["DAS28 >5.1","High activity"]]]]},{"id":"uploaded-153500","title":"Migraine — CGRP Preventive Medications","group":"Neurology & Immunology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153500"],"sections":[["Migraine prevention",[["Aimovig (erenumab)","70 mg SC every month; some patients 140 mg every month"],["Emgality (galcanezumab)","240 mg SC loading, then 120 mg monthly"],["Response reassessment","At 12 weeks; source references ≥50% episodic or ≥30% chronic migraine reduction"]]]]},{"id":"uploaded-153509","title":"Other Specialized Medications — Reference","group":"Medication Protocols","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153509"],"sections":[["Specialized medications",[["Leqvio (inclisiran)","284 mg SC initially, at 3 months, then every 6 months"],["Adakveo (crizanlizumab)","Historical source: 5 mg/kg IV at weeks 0 and 2 then every 4 weeks; regulatory status must be checked"],["Ofev (nintedanib)","150 mg orally twice daily for idiopathic pulmonary fibrosis (when tolerated)"]]]]},{"id":"uploaded-153541","title":"Crohn Disease — Evaluation and Risankizumab","group":"Gastroenterology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153541"],"sections":[["Crohn disease",[["Diagnosis in source","Ileocolonoscopy with histopathology; MR/CT enterography; fecal calprotectin"],["Skyrizi (risankizumab)","600 mg IV at weeks 0, 4 and 8; 360 mg SC at week 12 and every 8 weeks thereafter (source regimen)"]]]]},{"id":"uploaded-153705","title":"Laboratory Reference Values — Part 1","group":"Laboratory Reference Ranges","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153705"],"sections":[["Acid-base / electrolytes",[["pH","7.38–7.44"],["Bicarbonate","23–28 mEq/L"],["Sodium","136–145 mEq/L"],["Potassium","3.5–5.0 mEq/L"],["Chloride","98–106 mEq/L"],["PaCO₂","35–45 mmHg"],["PaO₂","80–100 mmHg"],["Oxygen saturation","≥95%"]]],["Hematology / iron",[["Hemoglobin","12–16 g/dL"],["Hematocrit","36–47%"],["Platelets","150–350 ×10³/µL"],["Ferritin","15–200 ng/mL"],["Serum iron","60–160 µg/dL"],["TIBC","250–460 µg/dL"],["Transferrin saturation","20–50%"],["Reticulocytes","0.5–1.5%"]]],["Metabolic / liver",[["Fasting glucose","70–100 mg/dL"],["Albumin","35–55 g/L"],["Total protein","60–78 g/L"],["ALT","0–35 U/L"],["AST","0–35 U/L"],["Amylase","0–130 U/L"],["BUN","8–20 mg/dL"],["Calcium","9–10.5 mg/dL"]]],["Reproductive hormones",[["AMH","1–3 ng/mL (source range)"],["Estradiol","Cycle-dependent; see original"],["Progesterone","Cycle-dependent; see original"],["FSH","Cycle-dependent; see original"],["LH","Cycle-dependent; see original"],["Prolactin","<20 ng/mL (source range)"]]]]},{"id":"uploaded-153733","title":"Laboratory Reference Values — Part 2","group":"Laboratory Reference Ranges","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["153733"],"sections":[["Biochemistry / endocrine",[["Total bilirubin","0.3–1.2 mg/dL"],["Direct bilirubin","0–0.3 mg/dL"],["PTH","10–65 ng/L"],["TSH","0.5–5.0 µU/mL"],["Total T4","5–12 µg/dL"],["Free T4","0.9–2.4 ng/dL"],["Total T3","70–195 ng/dL"],["Vitamin B12","200–800 pg/mL"],["25-OH Vitamin D","25–80 ng/mL (source range)"]]],["Coagulation / blood counts",[["aPTT","25–35 seconds"],["PT","11–13 seconds"],["RBC","4.2–5.9 ×10¹²/L"],["WBC","4–10 ×10⁹/L"]]],["Other markers",[["Troponin I","0–0.5 ng/mL (source; assay-dependent)"],["Troponin T","0–0.10 ng/mL (source; assay-dependent)"],["Rheumatoid factor","<40 U/mL"],["ALP","36–92 U/L"]]]]},{"id":"uploaded-153900","title":"Pediatric Respiratory Distress and Admission Criteria","group":"Pediatrics","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["153900"],"nodes":{"s":{"text":"Child with suspected pneumonia: signs of respiratory distress or hypoxemia?","choices":{"Yes":"admit","No":"risk"}},"risk":{"text":"Age <3–6 months with suspected bacterial CAP, virulent pathogen or unreliable follow-up?","choices":{"Yes":"admit","No":"out"}},"admit":{"end":"Hospital assessment / admission indicated according to severity and clinical context"},"out":{"end":"Consider outpatient management if clinically stable and safe follow-up possible"}},"start":"s"},{"id":"uploaded-154039","title":"Glycemic Targets — Nonpregnant Adults","group":"Endocrinology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["154039"],"nodes":{"s":{"text":"Nonpregnant adult with diabetes: individualize HbA1c target","choices":{"Short disease duration, long life expectancy, low hypoglycemia risk":"strict","Most adults":"standard","Severe hypoglycemia, major comorbidity, limited life expectancy":"relaxed"}},"strict":{"end":"Consider HbA1c around 6.5% if safely achievable"},"standard":{"end":"Common HbA1c goal <7%"},"relaxed":{"end":"Less stringent goal around 8% may be appropriate"}},"start":"s"},{"id":"uploaded-154237","title":"Diffuse Abdominal Pain — Differential Diagnosis","group":"Gastroenterology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["154237"],"sections":[["Diffuse abdominal pain differential",[["Bowel obstruction","Crampy abdominal pain, vomiting, distension, constipation"],["Perforation / acute mesenteric ischemia","Severe abdominal pain; urgent evaluation"],["Inflammatory bowel disease","Chronic/recurrent abdominal pain with diarrhea and systemic features"],["Spontaneous bacterial peritonitis","Especially in patients with ascites"],["Pancreatitis","Abdominal pain with nausea/vomiting"],["Metabolic / other","DKA, adrenal insufficiency, constipation, medication-related, lactose intolerance"]]]]},{"id":"uploaded-154310","title":"Endometrioma — Evaluation and Management","group":"Obstetrics & Gynecology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["154310"],"nodes":{"s":{"text":"Likely endometrioma on baseline assessment: symptoms, pelvic examination, ultrasound, malignancy risk, fertility preferences","next":"alarm"},"alarm":{"text":"Alarm findings or high suspicion for malignancy?","choices":{"Yes":"surg","No":"cancer"}},"cancer":{"text":"Imaging / clinical risk factors suggest ovarian cancer?","choices":{"Yes":"surg","No":"symptoms"}},"symptoms":{"text":"Endometrioma-related symptoms?","choices":{"Yes":"options","No":"surv"}},"options":{"text":"Discuss initial medical therapy for mild symptoms, or medical/surgical options for moderate–severe symptoms","choices":{"Surgery":"surg","Medical therapy":"reassess"}},"reassess":{"text":"Reassess after 6 months: adequately controlled?","choices":{"Yes":"continue","No":"surg"}},"continue":{"end":"Continue medical management and reassess at 6–12 month intervals"},"surv":{"end":"Active surveillance of asymptomatic patients; repeat assessment/imaging as indicated"},"surg":{"end":"Surgical assessment: cystectomy versus oophorectomy according to indication and patient preference"}},"start":"s"},{"id":"uploaded-154342","title":"Endometrioma — Surgical Management","group":"Obstetrics & Gynecology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["154342"],"nodes":{"s":{"text":"Endometrioma: are there concerns for malignancy? (concerning imaging, high-risk family/genetic history, patient concern)","choices":{"Yes":"ooph","No":"pref"}},"pref":{"text":"Does the patient desire definitive surgery with ovary removal? (prior recurrence, persistent symptoms, completed childbearing, preference)","choices":{"Yes":"ooph","No":"cyst"}},"ooph":{"end":"Consider oophorectomy; discuss ovarian function, fertility and consequences of bilateral removal"},"cyst":{"end":"Consider cystectomy (endometrioma removal only); preserves ovarian tissue but recurrence and surgical risks remain"}},"start":"s"},{"id":"uploaded-154414","title":"Upper Gastrointestinal Endoscopy — Indications","group":"Gastroenterology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"digital-reference","sourceImages":["154414"],"sections":[["Diagnostic EGD indications",[["Upper abdominal symptoms","Persistent symptoms despite therapy or alarm features"],["Dysphagia / odynophagia","Evaluate esophageal causes"],["Reflux","Persistent or recurrent despite therapy"],["GI bleeding / anemia","Evaluate upper gastrointestinal source"],["Abnormal imaging","Investigate suspected upper GI pathology"]]],["Therapeutic EGD",[["Hemostasis","Treat bleeding lesions"],["Dilation","Strictures"],["Foreign body","Removal"],["Polyps / selected lesions","Endoscopic removal or therapy"],["Feeding access","Placement of feeding / drainage tubes"]]]]},{"id":"uploaded-154612","title":"Palpable Breast Abnormalities — Age 40 and Over","group":"Breast & Oncology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["154612"],"nodes":{"s":{"text":"Palpable breast abnormality, age ≥40: imaging BI-RADS assessment","choices":{"BI-RADS 1":"one","BI-RADS 2":"two","BI-RADS 3":"three","BI-RADS 4 or 5":"four"}},"one":{"end":"Breast ultrasound; follow pathway for sonographically evaluated palpable abnormalities"},"two":{"end":"Return to routine screening as appropriate to clinical findings"},"three":{"text":"Breast ultrasound: lesion visualized?","choices":{"Yes":"us","No":"mam"}},"us":{"end":"Repeat ultrasound every 6–12 months for 2–3 years; biopsy if enlargement (source pathway)"},"mam":{"end":"Repeat mammography every 6–12 months for 2–3 years; biopsy if enlargement (source pathway)"},"four":{"text":"Breast ultrasound: lesion visualized?","choices":{"Yes":"core","No":"stereo"}},"core":{"end":"Ultrasound-guided core needle biopsy; management according to pathology concordance"},"stereo":{"end":"Stereotactic core needle biopsy; management according to pathology concordance"}},"start":"s"},{"id":"uploaded-154923","title":"Dyspepsia in Adults — Evaluation and Management","group":"Gastroenterology","description":"Digitally structured from supplied source; original image available below for comparison","kind":"flow","sourceImages":["154923"],"nodes":{"s":{"text":"Adult with dyspepsia: age ≥60, significant weight loss, overt GI bleeding, rapidly progressive alarm features or multiple alarm symptoms?","choices":{"Yes":"egd","No":"hp"}},"egd":{"text":"Upper GI endoscopy with gastric biopsy / H. pylori evaluation","choices":{"Organic disease":"treat","No organic disease":"func"}},"treat":{"end":"Treat underlying organic disease"},"func":{"end":"Consider functional dyspepsia; review H. pylori results"},"hp":{"end":"Noninvasive H. pylori testing: stool antigen or urea breath test; subsequent steps not visible in supplied crop"}},"start":"s"}];

